from pathlib import Path
from html.parser import HTMLParser
class Page(HTMLParser):
 def __init__(self):
  super().__init__()
  self.active=False
  self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag=='main': self.active=True
 def handle_endtag(self,tag):
  if tag=='main': self.active=False
 def handle_data(self,data):
  if self.active and data.strip(): self.parts.append(data.strip())
p=Page()
p.feed(Path('products/services/wordpress-migration-qa-pilot/raw/rsl-project.html').read_text())
print('\n'.join(p.parts)[:6500])
